// ═══════════════════════════════════════════════════════════════════════════
// refreshControls — actualiza colores y visibilidad según estado
// ═══════════════════════════════════════════════════════════════════════════
static void refreshControls() {
    if (!s_heatOn || !s_roomSp || !s_waterSp || !s_fanMode) return;

    bool heat   = (s_heatOn->getIntValue() != 0);
    int  fanVal = s_fanMode->getIntValue();   // -1=eco, -2=high, 0=off, 1-10=numérico

    // ── Calefacción ──────────────────────────────────────────────────────
    lv_label_set_text(s_heatBtnLbl, heat ? "ENCENDIDO" : "APAGADO");
    lv_obj_set_style_bg_color(s_heatBtn,
        lv_color_hex(heat ? C_HEAT_ON : C_BTN_OFF), LV_PART_MAIN);

    // ── Setpoint de temperatura ──────────────────────────────────────────
    if (heat) {
        lv_obj_remove_flag(s_spRow, LV_OBJ_FLAG_HIDDEN);
        char buf[12];
        snprintf(buf, sizeof(buf), "%.1f\xc2\xb0""C", s_roomSp->getFloatValue());
        lv_label_set_text(s_spLbl, buf);
    } else {
        lv_obj_add_flag(s_spRow, LV_OBJ_FLAG_HIDDEN);
    }

    // ── Ventilador ───────────────────────────────────────────────────────
    if (heat) {
        // Modo calefacción: 3 botones de nivel de ventilador
        lv_obj_remove_flag(s_fanHeatingRow, LV_OBJ_FLAG_HIDDEN);
        lv_obj_add_flag(s_fanOffRow,    LV_OBJ_FLAG_HIDDEN);
        lv_obj_add_flag(s_fanLevelRow,  LV_OBJ_FLAG_HIDDEN);

        String fanStr = s_fanMode->getStringValue();
        for (int i = 0; i < FAN_HEAT_N; i++) {
            lv_obj_set_style_bg_color(s_fanBtn[i],
                lv_color_hex((fanStr == FAN_STR[i]) ? C_BTN_ON : C_BTN_OFF),
                LV_PART_MAIN);
        }
    } else {
        // Modo apagado: On/Off + control de nivel
        lv_obj_add_flag(s_fanHeatingRow, LV_OBJ_FLAG_HIDDEN);
        lv_obj_remove_flag(s_fanOffRow,  LV_OBJ_FLAG_HIDDEN);

        bool fanOn = (fanVal != 0);   // cualquier valor ≠ 0 = ventilación activa
        // El Truma ignora comandos de ventilador mientras el boiler está calentando.
        // Deshabilitar controles para evitar cambios accidentales que se aplicarían
        // al siguiente ciclo del boiler.
        bool boilerActive = (s_waterSp && s_waterSp->getStringValue() != "off");

        // Sincronizar s_fanLevel si el valor actual es numérico
        if (fanVal > 0) s_fanLevel = fanVal;

        // Mostrar fila de nivel sólo si ventilador está on Y boiler no activo
        if (fanOn && !boilerActive) {
            lv_obj_remove_flag(s_fanLevelRow, LV_OBJ_FLAG_HIDDEN);
        } else {
            lv_obj_add_flag(s_fanLevelRow, LV_OBJ_FLAG_HIDDEN);
        }

        if (boilerActive) {
            lv_obj_add_state(s_fanOnBtn,  LV_STATE_DISABLED);
            lv_obj_add_state(s_fanOffBtn, LV_STATE_DISABLED);
        } else {
            lv_obj_remove_state(s_fanOnBtn,  LV_STATE_DISABLED);
            lv_obj_remove_state(s_fanOffBtn, LV_STATE_DISABLED);
        }

        lv_obj_set_style_bg_color(s_fanOnBtn,
            lv_color_hex(fanOn  ? C_BTN_ON : C_BTN_OFF), LV_PART_MAIN);
        lv_obj_set_style_bg_color(s_fanOffBtn,
            lv_color_hex(!fanOn ? C_BTN_ON : C_BTN_OFF), LV_PART_MAIN);

        char buf[4];
        snprintf(buf, sizeof(buf), "%d", s_fanLevel);
        lv_label_set_text(s_fanLevelLbl, buf);
    }

    // ── Caldera / Agua caliente ──────────────────────────────────────────
    String boiler = s_waterSp->getStringValue();
    for (int i = 0; i < BOILER_N; i++) {
        lv_obj_set_style_bg_color(s_boilerBtn[i],
            lv_color_hex((boiler == BOILER_STR[i]) ? C_BTN_ON : C_BTN_OFF),
            LV_PART_MAIN);
    }
}

// ═══════════════════════════════════════════════════════════════════════════
// Callbacks
// ═══════════════════════════════════════════════════════════════════════════
static void heatCb(lv_event_t*) {
    if (!s_heatOn) return;
    bool turningOff = (s_heatOn->getIntValue() != 0);
    s_heatOn->setValue(String(turningOff ? "0" : "1"));
    // Al apagar la calefacción, forzar ventilador a off
    if (turningOff && s_fanMode)
        s_fanMode->setValue(String("off"));
    refreshControls();
}

static void spDownCb(lv_event_t*) {
    if (!s_roomSp) return;
    double v = s_roomSp->getFloatValue() - 0.5;
    if (v >= 5.0) s_roomSp->setValue(v);
    refreshControls();
}

static void spUpCb(lv_event_t*) {
    if (!s_roomSp) return;
    double v = s_roomSp->getFloatValue() + 0.5;
    if (v <= 30.0) s_roomSp->setValue(v);
    refreshControls();
}

static void boilerCb(lv_event_t* e) {
    if (!s_waterSp) return;
    int idx = (int)(intptr_t)lv_event_get_user_data(e);
    // Al activar el boiler forzar ventilador a off: el Truma aplica comandos
    // de ventilador pendientes al ciclar, causando arranques inesperados.
    if (idx != 0 && s_fanMode)
        s_fanMode->setValue(String("off"));
    s_waterSp->setValue(String(BOILER_STR[idx]));
    refreshControls();
}

// Ventilador — modo calefacción (eco/alto/apag)
static void fanHeatCb(lv_event_t* e) {
    if (!s_fanMode) return;
    int idx = (int)(intptr_t)lv_event_get_user_data(e);
    s_fanMode->setValue(String(FAN_STR[idx]));
    refreshControls();
}

// Ventilador — modo apagado
static void fanOnCb(lv_event_t*) {
    if (!s_fanMode) return;
    if (s_waterSp && s_waterSp->getStringValue() != "off") return;  // boiler activo
    s_fanMode->setValue(String(s_fanLevel));
    refreshControls();
}

static void fanOffCb(lv_event_t*) {
    if (!s_fanMode) return;
    if (s_waterSp && s_waterSp->getStringValue() != "off") return;  // boiler activo
    s_fanMode->setValue(String("off"));
    refreshControls();
}

static void fanLevelDownCb(lv_event_t*) {
    if (!s_fanMode) return;
    if (s_waterSp && s_waterSp->getStringValue() != "off") return;  // boiler activo
    if (s_fanLevel > 1) {
        s_fanLevel--;
        if (s_fanMode->getIntValue() > 0)
            s_fanMode->setValue(String(s_fanLevel));
        refreshControls();
    }
}

static void fanLevelUpCb(lv_event_t*) {
    if (!s_fanMode) return;
    if (s_waterSp && s_waterSp->getStringValue() != "off") return;  // boiler activo
    if (s_fanLevel < 10) {
        s_fanLevel++;
        if (s_fanMode->getIntValue() > 0)
            s_fanMode->setValue(String(s_fanLevel));
        refreshControls();
    }
}

static void energyDdCb(lv_event_t* e) {
    lv_obj_t* dd = (lv_obj_t*)lv_event_get_target(e);
    s_energyMode = (int)lv_dropdown_get_selected(dd);
    // TODO (main.cpp): leer cydGetEnergyMode() y llamar
    //   energySelectFrame.setEnergySelection((TEnergySelection)s_energyMode);
    //   powerLimitFrame.setPowerLimit((TEnergySelection)s_energyMode);
}

